def completed_quarter_hour_rounds(login_time, logout_time):
    def minutes(value):
        return int(value[:2]) * 60 + int(value[3:])
    login = minutes(login_time)
    logout = minutes(logout_time)
    if logout < login:
        logout += 24 * 60
    first_start = (login + 14) // 15
    last_end = logout // 15
    return max(0, last_end - first_start)

